public boolean isValidDiscountValue(
    RetailPriceDiscPct _lowestValue,
    RetailMultibuyDiscountLine _multibuyDiscountLine)
{
    boolean ret = next isValidDiscountValue(_lowestValue, _multibuyDiscountLine);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) 
        && this.MultibuyDiscountType == RetailDiscountTypeEnum::UnitPriceDiscAmt)
    {
        ret = _multibuyDiscountLine.priceDiscPct >= _lowestValue;
    }

    return ret;
}

public void copyMultibuyDiscountInfo(RetailDiscountMultibuy _original)
{
    next copyMultibuyDiscountInfo(_original);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        this.ShouldUseInterval = _original.ShouldUseInterval;
    }
}

[DataEventHandler(tableStr(RetailDiscountMultibuy), DataEventType::ModifiedField)]
public static void RetailDiscountMultibuy_onModifiedField(Common sender, DataEventArgs e)
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        ModifyFieldEventArgs args = e;
        RetailDiscountMultibuy multibuy = sender;

        if (args.parmFieldId() == fieldNum(RetailDiscountMultibuy, MultibuyDiscountType)
            && multibuy.MultibuyDiscountType != RetailDiscountTypeEnum::UnitPriceDiscAmt)
        {
            multibuy.ShouldUseInterval = NoYes::No;
        }
    }
}
